-- i18n Phase B: 영어 콘텐츠 시드 (승인 후 적용). 한국어 원문은 그대로 두고 *_en 컬럼만 채움.
begin;
update checklist_items set title_en='Map out your 4-year course plan — start with the math track', why_how_en='This is where your path to Calculus by 12th grade gets decided — check your school''s math sequence, and if the path doesn''t reach it, plan summer catch-up now' where id=1;
update checklist_items set title_en='Build a GPA routine', why_how_en='9th grade grades count toward your GPA as-is — homework and test-prep routines are easiest to set in the first semester, and they become the start of your upward curve' where id=2;
update checklist_items set title_en='Try 2–3 activities of different types', why_how_en='Right now the goal is finding what you want to keep doing, not what you''re good at — pick different types, like making things, working with people, or writing' where id=3;
update checklist_items set title_en='Confirm your school''s international accreditation (WASC, Cognia, etc.) and that a school profile exists', why_how_en='This determines how much outside credibility your transcript carries — ask the school office directly, and if there is none, shift toward external indicators like AP and SAT' where id=4;
update checklist_items set title_en='Increase your English exposure (foundation, not test prep)', why_how_en='TOEFL is still far off — a habit of consuming English content in your area of interest every day is what builds the score later' where id=5;
update checklist_items set title_en='Sign up for 10th grade courses — include an Honors challenge', why_how_en='Ideally rigor steps up one level each year — add 1–2 Honors courses at a level you can handle' where id=6;
update checklist_items set title_en='Filter the activities you tried — keep only what you''ll continue', why_how_en='Keeping everything makes everything shallow — decide by "do I want to do this next semester too?" and cut down to 2 or fewer' where id=7;
update checklist_items set title_en='Make a summer plan', why_how_en='9th grade summer is for low-pressure exploration — one free, self-directed activity is enough; this is not the time you need an expensive camp' where id=8;
update checklist_items set title_en='Review first-year grades — plan to shore up weak subjects', why_how_en='AOs look at the trend — a subject that wobbled in 9th grade can be covered by a rise in 10th, so find the cause now' where id=9;
update checklist_items set title_en='Do 1 exploration activity in your area of interest', why_how_en='It doesn''t need to produce anything — confirming "is this field right for me?" is this summer''s goal' where id=10;
update checklist_items set title_en='Build a reading-and-note habit in your area of interest', why_how_en='The notes you leave from reading become essay material later — even a short reaction is worth writing down' where id=11;
update checklist_items set title_en='Take a practice PSAT', why_how_en='The goal is experiencing the format, not the score — test-day feel changes a lot after one real run' where id=12;
update checklist_items set title_en='Settle into your first AP/Honors course', why_how_en='Protecting your grade in a harder course is this semester''s top priority — practice raising rigor and holding GPA at the same time' where id=13;
update checklist_items set title_en='Start going deep on activities — the widening phase is over', why_how_en='From here on, dig deep into the activities you kept — add a new one only if it connects to what you already have' where id=14;
update checklist_items set title_en='Build trust with potential recommenders inside their classes', why_how_en='Recommendation letters can''t be crammed — pick candidate teachers to ask in 11th grade and become a student they remember through questions and participation' where id=15;
update checklist_items set title_en='Finalize your 11th grade AP lineup', why_how_en='APs are requested the year before — decide this month whether the core APs for your major are included, and if they''re not offered, plan to self-study and sit the exam' where id=16;
update checklist_items set title_en='Take AP exams (if you''re enrolled)', why_how_en='Your first AP score is a dress rehearsal — a 5 is nice, but the experience of running the exam itself is an asset for the multi-subject season in 11th grade' where id=17;
update checklist_items set title_en='Decide when to start SAT prep', why_how_en='The standard rhythm is start in 10th grade summer → first sitting in 11th grade fall — the higher your target tier, the more you should keep this rhythm' where id=18;
update checklist_items set title_en='Lock in a summer deep-dive activity', why_how_en='10th grade summer is the last window to build a spike — turn one of project, research, or service into a concrete plan' where id=19;
update checklist_items set title_en='Start your deep-dive activity', why_how_en='Make, don''t just participate — aim to end the summer with one thing you can "show"' where id=20;
update checklist_items set title_en='Start SAT fundamentals', why_how_en='Begin with a diagnostic practice test to find your starting point → study around weak areas — free official materials (Khan Academy) are enough at this stage' where id=21;
update checklist_items set title_en='Decide whether you need TOEFL', why_how_en='Waiver criteria differ by target school — some waive it based on years at an international school, so check against your target list before planning' where id=22;
update checklist_items set title_en='Take the real PSAT', why_how_en='11th grade PSAT is the real thing — a rehearsal right before the SAT and a check on where you stand' where id=23;
update checklist_items set title_en='Register for and take your first SAT', why_how_en='First sitting in fall → retake in spring is the standard — delaying the first sitting erases your retake chance; secure a test center early' where id=24;
update checklist_items set title_en='Set up a routine for managing multiple APs', why_how_en='11th grade is the year of maximum load — without a weekly routine per subject, every subject wobbles at once' where id=25;
update checklist_items set title_en='Secure a leadership position or create one yourself', why_how_en='AOs look at what you built, not the title — if an officer role in an existing club is hard to get, start something yourself, however small' where id=26;
update checklist_items set title_en='Go for external validation — check competition and submission deadlines', why_how_en='This is the last year of harvest that goes on your application — build a deadline calendar now so you don''t miss spring opportunities' where id=27;
update checklist_items set title_en='Line up 2 teachers for recommendation letters', why_how_en='Asking in 12th grade fall is too late — starting now, create material for the letter in those classes (questions, projects, growth)' where id=28;
update checklist_items set title_en='Retake and wrap up the SAT', why_how_en='The goal is to finish within spring — summer and fall belong to essays and applications' where id=29;
update checklist_items set title_en='Run your AP exam season', why_how_en='Multiple exams are a test of stamina — set priorities per subject and concentrate on 5s in the subjects related to your major' where id=30;
update checklist_items set title_en='Draft your college list', why_how_en='The reach/match/safety balance is key — use the tool''s browse view and your position marker to pick 3–4 schools per group' where id=31;
update checklist_items set title_en='Wrap up TOEFL', why_how_en='Finish before SAT and applications pile up — if it slips past summer, schedules collide' where id=32;
update checklist_items set title_en='Formally ask for recommendation letters', why_how_en='Asking before the school year ends is both courteous and safe — it gives teachers time to write over the summer' where id=33;
update checklist_items set title_en='Finish a draft of your main application essay', why_how_en='There''s no time to write in 12th grade fall — summer draft, fall revision is the standard rhythm' where id=34;
update checklist_items set title_en='Wrap up and organize your signature activity', why_how_en='Get your spike into a "showable form" — organizing outputs, numbers, and records now makes the activities section easy' where id=35;
update checklist_items set title_en='Finalize your college list + decide your ED/EA strategy', why_how_en='ED is a card that binds you to enroll if admitted — decide with your true first choice and financial situation together' where id=36;
update checklist_items set title_en='Start discussing financial documents', why_how_en='Documents like bank balance certificates take time with your parents — this also ties into your strategy for need-aware schools, so start the conversation in summer' where id=37;
update checklist_items set title_en='Create a Common App account and draft the activities section', why_how_en='The 10 activity slots take longer than you''d think — practice compressing each activity into 150 characters now' where id=38;
update checklist_items set title_en='Submit ED/EA applications — manage by counting back from deadlines', why_how_en='Count back from the date everything is sent, not the deadline — recommendation letters and transcripts are sent by others, not you, so buffer is essential' where id=39;
update checklist_items set title_en='Finish the main essay + start supplemental essays', why_how_en='Supplements are the real volume — organize each school''s prompts in a spreadsheet so you can reuse overlapping topics' where id=40;
update checklist_items set title_en='Confirm transcript and recommendation delivery — name a specific person in charge', why_how_en='Without a dedicated counselor, it''s unclear who sends what — pin down who sends it and when, by name and date' where id=41;
update checklist_items set title_en='Submit the CSS Profile and financial certification', why_how_en='Financial aid documents have different deadlines from applications — track each school''s required documents and deadlines separately' where id=42;
update checklist_items set title_en='Keep up your 12th grade grades', why_how_en='The #1 reason for rescinded admissions is a sharp drop in grades — your classes are still being evaluated during application season' where id=43;
update checklist_items set title_en='Organize RD results and build a comparison table', why_how_en='Compare by conditions, not emotions — put tuition, financial aid, and major conditions in one table' where id=44;
update checklist_items set title_en='Review financial aid offers and check appeal options', why_how_en='Some offers have room for negotiation — another school''s offer can serve as grounds' where id=45;
update checklist_items set title_en='Make your final choice and pay the deposit', why_how_en='Check the enrollment decision deadline — double depositing violates the rules, so only one' where id=46;
update checklist_items set title_en='Apply for the I-20 and prepare for the visa interview', why_how_en='Start as soon as admission is confirmed — interviews pile up in summer, and if you''re late your departure date is at risk' where id=47;
update checklist_items set title_en='Handle the waitlist (if applicable)', why_how_en='A letter of continued interest (LOCI) only works when you have new updates — a formulaic letter is meaningless' where id=48;
update checklist_items set title_en='Prepare for enrollment — housing, orientation, course registration', why_how_en='Emails from the admissions office keep coming all summer — missing one has real consequences, so set a routine of checking mail once a week' where id=49;
update checklist_items set title_en='Confirm your final transcript was sent', why_how_en='Name who sends it and confirm until it arrives — this is the last document' where id=50;
update checklist_items set title_en='Hand off your activities and tools', why_how_en='What you built lives on as legacy — pass materials, accounts, and know-how to younger students and leave a record' where id=51;
update checklist_items set title_en='Python basics + first mini project', why_how_en='The goal is graduating from following tutorials — a personal project that leaves an output is the start of a CS spike' where id=52;
update checklist_items set title_en='Take AP CS A or start self-studying it', why_how_en='Directly tied to the major and relatively easy to self-study, so it''s the #1 candidate for a self-study exam — no reason to give up even if it''s not offered' where id=53;
update checklist_items set title_en='Open a GitHub portfolio — get 1 project into a deployed state', why_how_en='"Does it have users?" separates project tiers — piling up unfinished projects is the most common trap' where id=54;
update checklist_items set title_en='Take USACO Bronze for the first time', why_how_en='Free, online, and open to international students — the goal is to gauge your level without pressure' where id=55;
update checklist_items set title_en='Confirm Calc (BC if possible) and CS A in your 11th grade AP lineup', why_how_en='If your school doesn''t offer them, make a self-study exam plan this month — non-accredited international schools should confirm an AP test site before 11th grade fall' where id=56;
update checklist_items set title_en='Check CS direct-admit status at every target school', why_how_en='Many schools admit CS by major, competition is far higher than the school-wide acceptance rate, and switching in is hard — checking the admission method is essential' where id=57;
update checklist_items set title_en='Consider whether you have room for AP Physics', why_how_en='Reinforces credibility for engineering-adjacent paths — next priority after Calc BC' where id=58;
update checklist_items set title_en='Attempt USACO promotion or 1 hackathon/submission-based competition', why_how_en='This is the year of harvest for your application — mistaking a paid coding camp certificate for an achievement is the trap' where id=59;
update checklist_items set title_en='Get real users for your signature project', why_how_en='A deployed app/website and user numbers are the core material for the activities section — deepen the existing project rather than starting a new one' where id=60;
update checklist_items set title_en='Organize portfolio links — README and demo video', why_how_en='Prepare a tech-stack summary for the application''s Additional Info too, and the activities section comes alive' where id=61;
update checklist_items set title_en='Intro to making — Arduino, 3D printing, build projects', why_how_en='Process records (build logs) matter as much as the output — build the record habit from the start' where id=62;
update checklist_items set title_en='Join a robotics team — if your school has none, prepare to found one', why_how_en='FTC/VEX etc. — if there''s no team, founding one is itself a leadership story' where id=63;
update checklist_items set title_en='Confirm 11th grade AP Physics (C or 1, matching your direction) + Calc BC lineup', why_how_en='Nail down one that fits your specific direction — if it''s ChemE, prioritize Chemistry' where id=64;
update checklist_items set title_en='Set up a routine for Calc BC + Physics C (or Chem) at the same time', why_how_en='This is the maximum-load year for this major — without a weekly routine per subject, every subject wobbles at once' where id=65;
update checklist_items set title_en='Secure a clearly defined part on the team — design/coding/drive, etc.', why_how_en='An unclear role in team competitions ("team member 1") is the trap — you must be able to name the part you owned' where id=66;
update checklist_items set title_en='Take F=ma / physics olympiad or Science Olympiad', why_how_en='The last harvest season for external validation that goes on your application' where id=67;
update checklist_items set title_en='Complete 1 personal build', why_how_en='Make, don''t just participate — aim to leave photos, a build log, and results' where id=68;
update checklist_items set title_en='Organize your build portfolio — photos, build log, results', why_how_en='Goes into the application along with competition results' where id=69;
update checklist_items set title_en='Start small real-world experience — join school sales or fundraising', why_how_en='Get a feel for it with something that has real money, customers, and results — execution over titles' where id=70;
update checklist_items set title_en='Check for a DECA/FBLA chapter — if none, push to found one', why_how_en='Founding a chapter is a bigger story than participating' where id=71;
update checklist_items set title_en='Plan to take or self-study AP Econ (Micro/Macro) + confirm 11th grade Calc', why_how_en='A set directly tied to the major and relatively easy to self-study — top colleges see economics as close to a math major, and BC is even better' where id=72;
update checklist_items set title_en='Plan and start a real project — one with real money and customers', why_how_en='A title with no execution, like "startup club member," is the trap — an activity with real numbers, even 10,000 KRW in revenue, wins' where id=73;
update checklist_items set title_en='Enter a team competition like the Wharton investment competition', why_how_en='Free, online, team-based — check the deadline calendar ahead of time' where id=74;
update checklist_items set title_en='Check your AP Statistics and English Language lineup', why_how_en='This major leans heavily on case analysis and essays' where id=75;
update checklist_items set title_en='Build the numbers for your running project — revenue, users, growth rate', why_how_en='Quantitative records are what prove execution on the application' where id=76;
update checklist_items set title_en='Quantify project results for the application + name a successor', why_how_en='"X KRW in revenue, Y customers" — naming a successor also proves continuity' where id=77;
update checklist_items set title_en='Take AMC 8/10 for the first time', why_how_en='To gauge your level — open to international students; secure a test site early' where id=78;
update checklist_items set title_en='Start math club activities', why_how_en='In this major the track itself is the credential — build an environment where you solve problems together' where id=79;
update checklist_items set title_en='Retake AMC 10/12 — go for the AIME cutoff', why_how_en='Dropping the major because the score didn''t come is the trap — competitions are one path among several, and project or research paths are equally valid' where id=80;
update checklist_items set title_en='Confirm 11th grade Calc BC + consider AP Statistics alongside', why_how_en='In this major, stopping at AB is close to a negative signal' where id=81;
update checklist_items set title_en='First data project — 1 analysis of real data', why_how_en='Make it a report that leaves an output — if you''re heading toward data, CS A is near-essential too' where id=82;
update checklist_items set title_en='Start math tutoring or creating educational content', why_how_en='The signature path in this major for securing the leadership axis' where id=83;
update checklist_items set title_en='Attempt AIME or a Kaggle/data competition', why_how_en='AIME is in spring — the last harvest season for the application' where id=84;
update checklist_items set title_en='If you exhaust school math, plan to take the next courses (multivariable, etc.) online', why_how_en='If you''ve used up what the school offers, continuing on your own from there is the spike' where id=85;
update checklist_items set title_en='Organize project and competition results — wrap up student journal submissions for research', why_how_en='The time to convert your harvest into application form' where id=86;
update checklist_items set title_en='Work diligently through the 3 core sciences — no need to pick a direction yet', why_how_en='An exploration phase for finding your direction through science club, in-school experiments, and documentaries' where id=87;
update checklist_items set title_en='Enter Science Olympiad or the school science fair', why_how_en='The start of a validation line that runs school → regional → international' where id=88;
update checklist_items set title_en='Set your major direction → sign up for the matching AP science in 11th grade', why_how_en='You must have one in your own direction — Calc BC recommended for physics/chemistry, AB + Statistics also valid for biology' where id=89;
update checklist_items set title_en='Start a self-designed experiment or data collection project', why_how_en='It doesn''t need to be a fancy lab — a literature review is a valid starting point too' where id=90;
update checklist_items set title_en='Deepen research — enter a regional science fair or submit to a student journal (JEI, etc.)', why_how_en='Submitting costs almost nothing and leaves an output, the best value path — using "program completion" itself as an achievement is the trap' where id=91;
update checklist_items set title_en='Consider adding an adjacent science AP', why_how_en='E.g., chemistry if you''re a bio major — a second axis builds credibility' where id=92;
update checklist_items set title_en='Wrap up research outputs — put publication and exhibition results on the application', why_how_en='What you discovered/built is the core — the output, not the certificate' where id=93;
update checklist_items set title_en='Secure a regular service placement — somewhere sustainable', why_how_en='Care homes, community welfare centers, etc. — design a 2-year routine, not a 2-week event; a one-off medical mission is the trap' where id=94;
update checklist_items set title_en='Grow your service role — participant → organizer + check for/consider founding a HOSA chapter', why_how_en='AOs rate 2 years of weekend service above 2 weeks of service abroad — role growth is the narrative' where id=95;
update checklist_items set title_en='Confirm AP Bio or Chem for 11th grade', why_how_en='The two required pre-med axes — one must be in 11th grade' where id=96;
update checklist_items set title_en='Consider AP Psychology and Statistics as reinforcement', why_how_en='Relevant to health fields + a foundation for medical research — high value relative to the load' where id=97;
update checklist_items set title_en='Do health-topic research or organize a campaign', why_how_en='Blood drive campaigns and health education content are realistic options in Korea' where id=98;
update checklist_items set title_en='Organize cumulative service hours and records', why_how_en='Numbers and records make the activities section easy' where id=99;
update checklist_items set title_en='Organize your service narrative — not hour counts but "why did you keep going?"', why_how_en='On this track, grade consistency is everything — do this alongside defending your GPA' where id=100;
update checklist_items set title_en='First MUN/debate participation + pick an issue you care about', why_how_en='The goal is to gauge your level — pick one issue and later activities connect to it' where id=101;
update checklist_items set title_en='Start creating content on your issue — blog or newsletter', why_how_en='The accumulated record of running it long-term is the spike — make current-affairs analysis part of daily life' where id=102;
update checklist_items set title_en='Confirm 11th grade AP in your direction (Psych/Gov/History) + consider Statistics', why_how_en='A choice that shows you understand social science as a data discipline' where id=103;
update checklist_items set title_en='Go for MUN chair or secretariat roles', why_how_en='Listing participation counts is the trap — role growth (delegate → chair → secretariat) is the narrative' where id=104;
update checklist_items set title_en='Enter an essay competition (John Locke, etc.) or run your own survey study', why_how_en='Evidence of digging into a question is this major''s validation' where id=105;
update checklist_items set title_en='Organize the cumulative record of your long-running content — issue count, subscribers', why_how_en='Continuity left in numbers is application material' where id=106;
update checklist_items set title_en='Start with the school magazine or literary journal — if none, consider founding one', why_how_en='Founding one is the best story — the starting point for building a body of writing' where id=107;
update checklist_items set title_en='Start a long-term writing project — serialized fiction, nonfiction, or criticism', why_how_en='"I read a lot" is not an activity — you need evidence that reading turned into writing' where id=108;
update checklist_items set title_en='Enter your first writing competition', why_how_en='Scholastic deadlines are in fall — check in advance whether international students can enter' where id=109;
update checklist_items set title_en='Confirm 11th grade AP English Lang + History — keep math on the AB line too', why_how_en='Top colleges look at math rigor even for humanities applicants (at least AB recommended)' where id=110;
update checklist_items set title_en='Enter competitions like Scholastic and John Locke in earnest', why_how_en='Submit to literary journals alongside — the year of harvest' where id=111;
update checklist_items set title_en='Complete your writing project or become literary journal editor-in-chief', why_how_en='One finished work or one leading role — one of the two this year' where id=112;
update checklist_items set title_en='Complete your signature work — the source for supplemental materials and essays', why_how_en='If you''re heading toward history, consider attempting The Concord Review (top-level difficulty)' where id=113;
update checklist_items set title_en='The year to make "a lot" of work — style experiments, sketchbook habit', why_how_en='Right now is when quantity builds quality' where id=114;
update checklist_items set title_en='Officially start accumulating portfolio pieces', why_how_en='A rushed, hagwon-style portfolio right before applications is the trap — US art schools look at consistency of perspective over technical polish' where id=115;
update checklist_items set title_en='Enter your first open call, like Scholastic', why_how_en='Fall deadline — your first outside exposure' where id=116;
update checklist_items set title_en='Plan AP Art History or core APs', why_how_en='Art schools within universities look at academics too — hold the core GPA defense line' where id=117;
update checklist_items set title_en='Start AP Art & Design — link it to your submission portfolio', why_how_en='Its portfolio-submission structure makes it a piece-accumulation process in itself' where id=118;
update checklist_items set title_en='Narrow your artistic world — make a series on a consistent theme', why_how_en='One perspective is stronger than scattered well-drawn pieces' where id=119;
update checklist_items set title_en='Organize a school exhibition', why_how_en='Double effect: leadership + exposure for your work' where id=120;
update checklist_items set title_en='Check every school''s portfolio requirements + finish 15–20 pieces for applications', why_how_en='Requirements differ by school — finalize what you''ve been editing since summer before the deadline' where id=121;
update checklist_items set title_en='Make 11th grade APs a "works for any major" combination — Calc + Eng Lang + 1 science + 1 history', why_how_en='The more undecided you are, balance core rigor rather than going all-in — "undecided" doesn''t mean "loose"; it means taking the highest level your school offers in each core' where id=122;
update checklist_items set title_en='Cut activities down to 1–2 + reset your major direction', why_how_en='Miss the moment to narrow and there''s no time left to build a spike — re-selecting your major in the tool is also for this season' where id=123;
update checklist_items set title_en='Start a sketchbook — observational drawings of nearby buildings and spaces', why_how_en='An architecture portfolio starts with "can you see?" — hand drawing is the first material' where id=124;
update checklist_items set title_en='Confirm 11th grade Physics + Studio Art', why_how_en='Take both axes, structure (physics) and portfolio (art), together in 11th grade' where id=125;
update checklist_items set title_en='Research university summer architecture programs and prepare to apply', why_how_en='Official university programs like Cornell and CMU — attending in 11th grade summer is typical, applications are in spring' where id=126;
update checklist_items set title_en='Check B.Arch vs BS/BA at target schools — organize portfolio requirements', why_how_en='5-year B.Arch programs commonly require a portfolio with a separate deadline' where id=127;
update checklist_items set title_en='Enter Scholastic Art & Writing (Architecture & Industrial Design)', why_how_en='A signature external validation open to international students' where id=128;
update checklist_items set title_en='Complete 5 core portfolio pieces', why_how_en='Summer is the only long stretch of production time' where id=129;
update checklist_items set title_en='Edit your portfolio per school + check separate deadlines', why_how_en='Some schools have portfolio deadlines that differ from the application deadline' where id=130;
update checklist_items set title_en='First experience with a health club or service', why_how_en='In nursing, a "record of caring for people" is the spike — the earlier you start, the more continuity you build' where id=131;
update checklist_items set title_en='Get CPR and first aid certification', why_how_en='An accessible first external validation, and needed for expanding your service role' where id=132;
update checklist_items set title_en='Confirm AP Biology and Chemistry for 11th grade', why_how_en='The two core courses for direct-entry BSN requirements' where id=133;
update checklist_items set title_en='Check direct-entry BSN vs 2+2 at target schools', why_how_en='Application strategy and deadlines differ completely depending on the admission method' where id=134;
update checklist_items set title_en='Enter a HOSA competition or apply to a university nursing summer program', why_how_en='International chapters and official programs only — check the once-a-year schedule' where id=135;
update checklist_items set title_en='Grow your service role — participant → organizing and teaching', why_how_en='Same principle as pre-med: 2 years of weekend service > a 2-week event' where id=136;
update checklist_items set title_en='Prepare cumulative service records and a science teacher recommendation', why_how_en='Both numbers and narrative — "why nursing?" from your records' where id=137;
update checklist_items set title_en='Start participating in school media (newspaper, broadcast, magazine)', why_how_en='The spike for a media major is a "record of publishing regularly"' where id=138;
update checklist_items set title_en='Confirm AP English Language for 11th grade', why_how_en='The basic course for evidence of writing' where id=139;
update checklist_items set title_en='First Scholastic Art & Writing entry (journalism, essay)', why_how_en='Open to international students, deadlines every fall to winter' where id=140;
update checklist_items set title_en='Secure an editing/planning role (editor-in-chief, section editor)', why_how_en='From participant to operator — role growth is the narrative' where id=141;
update checklist_items set title_en='Apply to a university summer journalism program', why_how_en='Official university programs only — check the once-a-year schedule' where id=142;
update checklist_items set title_en='Personal media project or organize 5 signature pieces', why_how_en='Outputs you can show via a link bring the activities section to life' where id=143;
update checklist_items set title_en='Edit 3–5 signature pieces + prepare links for the application', why_how_en='In a form ready to use directly in the application''s Additional Info and portfolio links' where id=144;
update prescriptions set text_en='Your rigor is in a good place — rather than adding more courses, protecting the grade trend in your current ones comes first.' where id=1;
update prescriptions set text_en='Rigor is sufficient, so now it''s time to focus on harvesting results (grades, AP scores) in each course.' where id=2;
update prescriptions set text_en='No need to push rigor any higher — in 12th grade, holding steady is the proof.' where id=3;
update prescriptions set text_en='You''re headed the right way — when you register for next semester, check whether you can handle one more Honors/AP course.' where id=4;
update prescriptions set text_en='Rather than raising everything at once, concentrate your effort on the rigor and grades of 1–2 courses tied to your major.' where id=5;
update prescriptions set text_en='Do your best within the courses already open to you, and focus on building an upward trend over the remaining semesters.' where id=6;
update prescriptions set text_en='You still have 3 of the 4 years left — start by correcting your math track at next semester''s course registration, and you have plenty of room to climb by 12th grade.' where id=7;
update prescriptions set text_en='Start now and you can make it up with your 11th-grade lineup — focus on two things: summer reinforcement and next year''s course registration.' where id=8;
update prescriptions set text_en='Given the time left, the realistic starting point is "an upward trend in the courses you''re taking now" — your current grade trajectory leaves a bigger mark on your application than chasing new courses.' where id=9;
update prescriptions set text_en='A 12th-grade grade increase is a signal AOs actually look at — focus on making your best final semester in the courses you have now.' where id=10;
update prescriptions set text_en='Good pace — keep to your plan; there''s no need to get far ahead on testing at this stage.' where id=11;
update prescriptions set text_en='Your score is secured — now reallocate the time you spent on testing to activities and application prep.' where id=12;
update prescriptions set text_en='Testing is done — all that''s left is your submission strategy: which scores go to which schools.' where id=13;
update prescriptions set text_en='This is the foundation phase — English exposure and math fundamentals are your test prep right now.' where id=14;
update prescriptions set text_en='This season, check whether you''re on the standard rhythm (start summer of 10th grade → first sitting fall of 11th).' where id=15;
update prescriptions set text_en='Lock in your first sitting within this season — put it off and you lose the chance to retake.' where id=16;
update prescriptions set text_en='First check whether scores from the remaining test dates can arrive by your deadlines (including ED/EA).' where id=17;
update prescriptions set text_en='It''s not too late — one diagnostic practice test to find your starting point is enough to build a plan.' where id=18;
update prescriptions set text_en='Before a target score, secure your calendar of remaining test dates — your testing schedule is your strategy.' where id=19;
update prescriptions set text_en='Rebuilding your list around test-optional schools is also a valid strategy — design an application that stands without a score.' where id=20;
update prescriptions set text_en='Your direction is already set — don''t broaden; add depth to what you''re doing now.' where id=21;
update prescriptions set text_en='This year''s job is to shape your main activity into a "showable" form (deliverables, numbers, records).' where id=22;
update prescriptions set text_en='No new activities needed — focus on organizing what you''ve built to fit the application format.' where id=23;
update prescriptions set text_en='Keep exploring — you need to try activities of different kinds before you can see what to keep.' where id=24;
update prescriptions set text_en='Now is the time to narrow down — keep only 1–2, using "do I want to keep doing this next semester?" as the test.' where id=25;
update prescriptions set text_en='This year''s goal is to produce one visible deliverable from the activities you kept.' where id=26;
update prescriptions set text_en='This is the best time to start — pick one thing you can begin alone and for free.' where id=27;
update prescriptions set text_en='Given the time left, the realistic starting point is digging deeper into what you already do daily (hobbies, classes, habits) rather than a new activity.' where id=28;
update prescriptions set text_en='You can''t change the number of activities now, but you can change the depth of how you describe them — focus on showing one activity concretely.' where id=29;
update prescriptions set text_en='You''ve got the title — now leave a record of what you built and changed in that role.' where id=30;
update prescriptions set text_en='Start taking on small responsibilities — one event, one part is where leadership begins.' where id=31;
update prescriptions set text_en='Create one experience where you led — if a club officer role is out of reach, starting something small yourself works too.' where id=32;
update prescriptions set text_en='Leadership is initiative, not a title — start by owning one small project from start to finish.' where id=33;
update prescriptions set text_en='Given the time left, the realistic starting point is expanding your role inside an existing activity — it builds faster than founding something new.' where id=34;
update prescriptions set text_en='Even without having led, you can concretely show your contribution within a team — the plain facts, no exaggeration, are enough.' where id=35;
update prescriptions set text_en='Organize your awards and recognitions ahead of time in application format (competition name, scale, level, year).' where id=36;
update prescriptions set text_en='Enter once to gauge your level — the goal isn''t the result but learning which competitions fit you.' where id=37;
update prescriptions set text_en='Build a calendar of competition and submission deadlines — this is the last year whose harvest goes into your application.' where id=38;
update prescriptions set text_en='Start with free, online competitions — making your first record where the barrier is low comes first.' where id=39;
update prescriptions set text_en='Competitions aren''t the only validation — every route that puts your work out in public counts: journal submissions, exhibitions, public releases.' where id=40;
update prescriptions set text_en='An application stands even without external awards — organize it to show the completeness and persistence of the work itself.' where id=41;
update prescriptions set text_en='Try tying your scattered records into one thread — just check whether your activities point toward the same question.' where id=42;
update prescriptions set text_en='The habit of keeping an activity log becomes the raw material for your story — even a short note each season.' where id=43;
update prescriptions set text_en='Working through the story-axis checklist items one by one — college list, recommendations, activity organization — is the prep itself.' where id=44;
update prescriptions set text_en='This isn''t the time to worry about a story — it''s the time to make the material (activities, records).' where id=45;
update prescriptions set text_en='Look for the links between your activities — the starting point is seeing whether they tie together as "one question I''ve kept holding on to."' where id=46;
update prescriptions set text_en='An account that reveals your real reasons for your choices beats a perfect narrative — start by gathering your record so far, exactly as it is.' where id=47;
update appeal_strategies set text_en='Academic rigor is your central axis — arrange your application so the consistency of your course choices and your upward grade trajectory show most clearly.' where id=1;
update appeal_strategies set text_en='Test scores are your central axis — while the scores prove your fundamentals, spend the rest of the application''s space on activities and your story.' where id=2;
update appeal_strategies set text_en='Your main activity is your central axis — unify the first slot of the activities section and the core material of your application around it.' where id=3;
update appeal_strategies set text_en='Experience leading is your central axis — instead of listing titles, order your writing around what you built and changed.' where id=4;
update appeal_strategies set text_en='External validation is your central axis — state your awards and publications clearly in application format, with scale and level.' where id=5;
update appeal_strategies set text_en='Your story is your central axis — make the thread connecting your activities to one question the structure of your whole application.' where id=6;
update appeal_strategies set text_en='No axis stands out yet — the realistic starting point is to pick the one axis that builds fastest at your grade from the remaining season''s checklist and focus there.' where id=7;
update glossary set term_en='need-blind / need-aware', definition_en='If applying for financial aid doesn''t affect the admission decision, it''s need-blind; if it''s considered, need-aware. Very few schools are need-blind for international students, so if you need aid, checking this distinction comes first when building your target list.' where id=1;
update glossary set term_en='direct admit', definition_en='Admission directly into a specific college or major at the point of entry. Those majors (especially CS, engineering, business) are far more competitive than the school overall, and switching in later can be hard, so check how your target schools admit ahead of time.' where id=2;
update glossary set term_en='demonstrated interest', definition_en='Factoring an applicant''s signals of interest — campus visits, info sessions, opening emails — into the review. If a school counts it, even low-cost actions like attending an online info session get recorded, so they''re worth doing.' where id=3;
update glossary set term_en='mid-50% (middle 50% range)', definition_en='When admitted students are lined up by score, the 25th–75th percentile band — the score range of the middle half. Reading where your score falls in this range to gauge "where I stand among admits" is the standard way to interpret scores.' where id=4;
update glossary set term_en='ED (Early Decision)', definition_en='A binding plan: you apply early in the fall and must enroll if admitted. It''s a card you can play at only one school, so use it only for a true first choice whose financial terms you''ve also confirmed.' where id=5;
update glossary set term_en='EA (Early Action)', definition_en='You apply early in the fall, but with no obligation to enroll. You get results early while keeping your options open, so if you have a ready application, it''s highly useful.' where id=6;
update glossary set term_en='REA (Restrictive Early Action)', definition_en='No obligation to enroll, but it restricts applying early to other private colleges at the same time. Used by a few top-tier schools, so read the restriction rules first when planning your early-application strategy.' where id=7;
update glossary set term_en='RD (Regular Decision)', definition_en='The standard plan: deadlines around the start of the year, decisions in spring. Most applications go here, so you''ll design your overall application timeline as a combination with early plans.' where id=8;
update glossary set term_en='rigor', definition_en='How demanding a combination of courses you chose out of what your school offers. AOs read your transcript alongside the school profile, so taking "the highest difficulty available at my school" is what managing rigor means.' where id=9;
update glossary set term_en='holistic review', definition_en='A review method that looks at grades, scores, activities, essays, and recommendations together. It means a weakness in one element can be offset by strength in another, so knowing your strong axis is where strategy starts.' where id=10;
update glossary set term_en='spike', definition_en='An admissions term for a sharp strength from digging deep into one area rather than doing many activities shallowly. Creating "the thing that comes to mind when you think of this student" is the heart of activity strategy.' where id=11;
update glossary set term_en='CDS (Common Data Set)', definition_en='Admission statistics colleges publish every year in the same format. It''s the primary source where you can check official data like score ranges and the importance of review factors yourself, so build the habit of reading it instead of rumors.' where id=12;
update glossary set term_en='Common App', definition_en='A shared application platform that lets you apply to hundreds of colleges at once. Its structure is fixed — 10 activity slots, a main essay, etc. — so organizing your records to fit this format makes application season much lighter.' where id=13;
update glossary set term_en='school profile', definition_en='The document your school sends to colleges introducing itself: grading system, courses offered, school characteristics. It''s the reference AOs use to interpret your transcript, so it''s important to check whether your school has one.' where id=14;
update glossary set term_en='TOEFL waiver', definition_en='A policy that waives the English proficiency test if you meet certain conditions (e.g., years enrolled at an English-medium school). Criteria differ by school, so once your target list is set, checking each school''s waiver rules first can reduce your testing load.' where id=15;
update glossary set term_en='CSS Profile', definition_en='A detailed financial document many private colleges use for financial aid review. Its deadlines run separately from the application, so if you need aid, put this document''s deadline into your application timeline too.' where id=16;
update glossary set term_en='I-20', definition_en='The document a school issues after admission certifying your student status — the prerequisite for a visa application. Issuance takes time, so apply as soon as you confirm enrollment to keep your departure schedule safe.' where id=17;
update glossary set term_en='deferral', definition_en='A decision in the early round that isn''t a rejection but pushes your review to the regular round. It means you still have a chance, so you prepare for re-review with new grades and achievement updates.' where id=18;
update glossary set term_en='waitlist', definition_en='A holding state — neither admitted nor denied — where you may be admitted later if a spot opens. Whether to stay on it is your choice, and if you stay, an appeal is only meaningful when you have new updates.' where id=19;
update glossary set term_en='test-optional', definition_en='A policy where the applicant chooses whether to submit test scores. It creates a decision rule — "submit if the score raises my standing, otherwise don''t" — so read it together with the mid-50%.' where id=20;
update glossary set term_en='LOCI (letter of continued interest)', definition_en='A letter of continued interest you send when staying on a waitlist. It only works when you have new grade, award, or activity updates; a pro-forma letter is meaningless.' where id=21;
update glossary set term_en='AP (Advanced Placement)', definition_en='College-level courses taken in high school and their standardized exams (scored 1–5). The main way to show rigor, and a 5 is external evidence of ability in your major area.' where id=22;
update glossary set term_en='weighted / unweighted GPA', definition_en='A GPA that adds bonus points for course difficulty is weighted; one on a plain 4.0 scale without them is unweighted. Schools and platforms use different standards, so always say which one when stating your GPA.' where id=23;
update glossary set term_en='reach / match / safety', definition_en='A classification of schools as above, at, or safely below your standing. Building a list balanced across these three groups is the basic skeleton of application strategy.' where id=24;
update glossary set term_en='supplemental essay', definition_en='Additional essays that individual schools require beyond the main essay. The workload grows sharply as your school count rises, so gathering the prompts early and grouping overlapping topics saves your fall.' where id=25;
update glossary set term_en='mid-year report', definition_en='An interim report sending your first-semester 12th-grade grades to colleges. It means grades still count in the review after you submit, so keeping up 12th-grade grades genuinely matters.' where id=26;
update glossary set term_en='superscore', definition_en='A scoring method that combines your best section scores across multiple sittings. If a school superscores, retaking is less of a burden, so check your target schools'' score policies and plan your sittings accordingly.' where id=27;
update glossary set term_en='rolling admission', definition_en='Applications are reviewed and decided as they arrive, with no fixed decision date. The earlier you apply, the more seats are open when you''re reviewed, so applying early is an advantage at these schools.' where id=28;
update glossary set term_en='ED II', definition_en='A second Early Decision round with the same binding commitment as ED but a winter deadline. It''s a second card you can play after seeing your ED result, so it becomes an option if your first choice changed or your prep ran late.' where id=29;
update glossary set term_en='F-1 visa', definition_en='The student visa for international students studying in the US, applied for on the basis of the I-20. Interview appointments pile up at certain times, so start the process right after confirming admission to keep your pre-enrollment schedule safe.' where id=30;
update basics set title_en='US admissions is holistic review', body_en='US colleges don''t cut by a single score; they look at grades, tests, activities, essays, and recommendations together.
That''s why "what score gets me in?" has no answer.
Instead, the strategy is to make each element describe one person.
Even if one element is weak, a strong one can make up for it.
This tool''s 6 axes are a map that makes those elements visible.' where id=1;
update basics set title_en='How much each factor weighs differs by school', body_en='The same application reads differently at each school.
Some schools officially state they weigh rigor more; others, essays or demonstrated interest.
Those criteria aren''t in rumors — they''re in each school''s Common Data Set and admissions pages.
So once your target schools are set, first check "what that school says it looks at."
This tool''s school cards are where that official information is gathered.' where id=2;
update basics set title_en='Narrow and deep beats wide and shallow', body_en='A student who dug deep into 2 activities is more memorable than one who did 10 shallowly.
AOs look at persistence and deliverables, not the number of activities.
Grades 9–10 are for exploring, but exploring needs an end point.
Once you''ve narrowed down, build a picture where your role grows and results accumulate within it.
If "the thing that comes to mind when you think of this student" exists, you''re on track.' where id=3;
update basics set title_en='Trend over snapshot', body_en='AOs look at the direction of 4 years, not one grade report from today.
A wobble in 9th grade can be fully covered by a rise in grades 10–11.
Conversely, a graph that starts strong and dips is a worse signal than good numbers are a good one.
So manage "where am I heading" rather than "what''s my score now."
The rhythm of coming back to check each season in this tool is that trend-management device.' where id=4;
update basics set title_en='What''s different for international students', body_en='International students have extra pieces: English proficiency proof like TOEFL, a visa (I-20), and financial documentation.
At most schools, applying for financial aid affects the review (need-aware), so your list strategy changes.
At many schools, admit rates also move separately for the international pool.
On the other hand, much of this is manageable simply by knowing the documents and timeline ahead of time.
This tool''s international-student items serve as that timetable.' where id=5;
update quiz_items set question_en='Test-optional schools don''t factor in an SAT score even if you submit one', explanation_2lines_en='If you submit it, it counts.
"Optional" means submitting is your choice, and a good score within the range is often better sent' where id=1;
update quiz_items set question_en='Even if admitted through ED (Early Decision), you can wait for other schools'' results before deciding to enroll', explanation_2lines_en='An ED admit comes with an obligation to enroll.
You must withdraw other applications, which is why ED is a card for a true first choice only' where id=2;
update quiz_items set question_en='Need-blind means the school gives out a lot of scholarship money', explanation_2lines_en='It means applying for aid doesn''t affect the admission decision.
How much aid they give is a separate question you have to check on its own' where id=3;
update quiz_items set question_en='You pick a major after enrolling anyway, so your choice of major when applying doesn''t matter much', explanation_2lines_en='Many schools admit by major (direct-admit).
Especially for CS, engineering, and nursing, your applied major changes admission difficulty, and switching is hard' where id=4;
update quiz_items set question_en='The overall admit rate a college publishes applies almost as-is to international students too', explanation_2lines_en='The international admit rate is usually lower than overall and counted separately.
When setting targets, look at the international-student numbers' where id=5;
update clarity_items set question_en='I''m clear on what major I want' where id=1;
update clarity_items set question_en='I can judge for myself whether my grades and activities match the level of my target colleges' where id=2;
update clarity_items set question_en='I know what I need to prepare at my current grade' where id=3;
update clarity_items set question_en='I understand the US admissions process (application plans, deadlines, documents)' where id=4;
update schools set intro_en='A private research university in Princeton, NJ, on a single residential campus in a suburban setting.', what_they_value_en='In its latest CDS (2025-26) C7, Princeton officially marks rigor of curriculum, class rank, GPA, standardized test scores, essays, recommendations, extracurricular activities, talent/ability, and character/personal qualities all as Very Important. The admissions office''s official page says it looks for students who have pursued academic excellence with intellectual curiosity and who make a difference in their schools and communities.', location_note_en='Located in a small college town between New York and Philadelphia, about an hour by train from either city, with a four-season Northeastern US climate.', gpa_note_en='72% of first-years had a high school GPA of 4.0 (CDS 2025-26 C11)' where id=1;
update schools set intro_en='A private, engineering- and science-focused university on the banks of the Charles River in Cambridge, MA, with an urban campus.', what_they_value_en='The admissions office''s official ''What we look for'' page names alignment with MIT''s mission (making the world better through science and technology), a collaborative spirit, initiative, willingness to take risks and fail, hands-on creativity, genuine immersion and curiosity in a few interests, and balance in life. In CDS 2025-26 C7, the only factor marked Very Important is character/personal qualities.', location_note_en='Part of the Boston metro area, with downtown Boston just across the Charles River; a Northeastern US climate with cold, snowy winters.', gpa_note_en='GPA distribution not reported (N/Av); 97% of first-years were in the top 10% of their high school class (CDS 2025-26 C10)' where id=2;
update schools set intro_en='A private research university in Cambridge, MA, with an urban campus.', what_they_value_en='The admissions office''s official ''What We Look For'' page lists its review criteria as growth and potential (have you reached your maximum capacity?), interests and activities (what have you done and what have you learned?), character (are you someone people would want to be around?), and potential contribution to the Harvard community. Note that in CDS 2025-26 C7, no factor is marked Very Important; most are marked only Considered.', location_note_en='Located in Cambridge, a college city in the Boston metro area, with a Northeastern US climate of cold, snowy winters.', gpa_note_en='74.7% of first-years had a high school GPA of 4.0 (CDS 2025-26 C11)' where id=3;
update schools set intro_en='A private research university in Stanford, CA (next to Palo Alto), with a large suburban campus.', what_they_value_en='In its latest CDS (2025-26) C7, Stanford officially marks rigor of curriculum, class rank, GPA, standardized test scores, essays, recommendations, extracurricular activities, talent/ability, and character/personal qualities all as Very Important. The admissions office''s official FAQ says that alongside academic excellence, it evaluates intellectual vitality that GPA and scores alone don''t reveal, plus sustained commitment and leadership in activities in and out of school.', location_note_en='Located in the heart of Silicon Valley in the San Francisco Bay Area, with a mild, dry California climate year-round.', gpa_note_en='73% of first-years had a high school GPA of 4.0 (CDS 2025-26 C11; average GPA 3.94/4.0 unweighted)' where id=4;
update schools set intro_en='A private research university in New Haven, CT, with a residential (residential college) campus in the center of a mid-sized city.', what_they_value_en='The admissions office''s official ''What Yale Looks For'' page frames its review around two questions — who will make the most of Yale''s resources, and who will contribute most to the Yale community — and names academic potential (a curious, sharp mind), concern for others and the common good, and a drive to stretch one''s own abilities. In CDS 2025-26 C7, rigor of curriculum, class rank, GPA, essays, recommendations, extracurricular activities, talent/ability, and character are marked Very Important (standardized tests are Considered).', location_note_en='A mid-sized port city about 2 hours by train from New York, with a four-season Northeastern US climate.', gpa_note_en='GPA distribution not reported; 97% of first-years were in the top 10% of their high school class (CDS 2025-26 C10)' where id=5;
update schools set intro_en='An urban campus in the Hyde Park neighborhood on the South Side of Chicago, Illinois.', what_they_value_en='The admissions office''s official application page states that no single factor — academic and activity record, essays, recommendations, SAT/ACT scores — decides admission on its own, and emphasizes that applicants should tell their own story in their own voice. Testing follows a test-optional ''No Harm'' policy: scores are officially considered only when they help the applicant.', location_note_en='About 11 km south of downtown Chicago, one of the three largest US cities, near Lake Michigan; winters are on the cold side.', gpa_note_en=NULL where id=6;
update schools set intro_en='A private research university with a suburban campus in Durham, North Carolina.', what_they_value_en='The official ''What We Look For'' page says Duke looks for ambition and curiosity, talent and persistence, energy and humanity, and names five evaluation factors: rigor of curriculum, grades, recommendations, activities, and essays. Per CDS 2025-26 C7, Very Important factors are rigor of secondary school record, GPA, recommendations, extracurricular activities, talent/ability, and character/personal qualities. (Source: admissions.duke.edu/what-we-look-for + CDS C7)', location_note_en='Located in Durham, a mid-sized city of about 280,000 in the Research Triangle region, with a large Gothic-style campus surrounded by forest.', gpa_note_en=NULL where id=7;
update schools set intro_en='A private research university in a residential area of north Baltimore, Maryland (undergraduates are on the Homewood campus).', what_they_value_en='The official FAQ states that across the whole application, Hopkins looks for academic character, impact and initiative, and overall match with the school. Per CDS 2025-26 C7, Very Important factors are rigor of secondary school record, class rank, GPA, standardized test scores, essays, and recommendations. (Source: apply.jhu.edu FAQ + CDS C7)', location_note_en='Located in Baltimore, a large city of about 570,000, on a green campus north of downtown, about an hour by car from Washington, D.C.', gpa_note_en='66.1% of first-years had a GPA of 4.0; average GPA 3.93 (CDS 2025-26 C11·C12)' where id=8;
update schools set intro_en='A private research university with a campus on the shore of Lake Michigan in Evanston, Illinois.', what_they_value_en='The official admissions office emphasizes holistic review combined with a commitment to college access, and says grades, rigor of curriculum, recommendations, awards, and essays are evaluated in the context of the applicant''s school and environment. Per CDS 2024-25 C7, Very Important factors are rigor of secondary school record, class rank, GPA, essays, recommendations, extracurricular activities, talent/ability, and character/personal qualities. (Source: admissions.northwestern.edu + CDS C7)', location_note_en='Located in Evanston (pop. about 75,000), a suburban city about 20 km north of downtown Chicago; the lakefront campus has cold, windy winters.', gpa_note_en=NULL where id=9;
update schools set intro_en='An Ivy League private university with a campus in the University City district just west of downtown Philadelphia, Pennsylvania.', what_they_value_en='The official ''What Penn Looks For'' page says that through whole-person review, Penn seeks students who embody Benjamin Franklin''s spirit — open, curious, creative, practical, and making connections across disciplines — and who are oriented toward service to society. Per CDS 2024-25 C7, Very Important factors are rigor of secondary school record, GPA, essays, recommendations, and character/personal qualities. (Source: admissions.upenn.edu What Penn Looks For + CDS C7)', location_note_en='An urban campus in Philadelphia, a large city of about 1.6 million, located between New York and Washington, D.C., with a four-season climate.', gpa_note_en='59% of first-years had a GPA of 4.0; average GPA 3.9 (CDS 2024-25 C11·C12)' where id=10;
update schools set intro_en='A small private university focused on science and engineering, in a suburban residential area of Pasadena, California (near Los Angeles).', what_they_value_en='CDS 2024-25 C7 marks rigor of secondary school record, standardized test scores, essays, recommendations, and character/personal qualities as Very Important. The official ''What We Look For'' page says Caltech values the abstract thinking and problem-solving that advanced math demands, that there is no set ''Caltech type,'' and that applications are evaluated in the context of each student''s school, region, and opportunities. (Source: admissions.caltech.edu What We Look For + CDS C7)', location_note_en='Located in Pasadena, a mid-sized city about 17 km northeast of downtown LA; a compact campus with a mild, dry Southern California climate year-round.', gpa_note_en='Among those who submitted class rank, 86.4% of first-years were in the top 10% of their high school class (CDS 2024-25 C10)' where id=11;
update schools set intro_en='Located in the small city of Ithaca, New York, on a large rural-style campus set on a hill.', what_they_value_en='In CDS 2024-25 C7, the factors officially marked ''Very Important'' are rigor, essays, recommendations, extracurricular activities, talent/ability, and character/personal qualities. Class rank and GPA are Important; test scores are Considered. The admissions office officially states that test scores are viewed in context alongside GPA, rigor, activities, essays, and recommendations. You apply directly to one of 8 colleges, so essays and requirements differ by college.', location_note_en='Ithaca is a college town of about 30,000, roughly 4 hours by car from New York City, with long, cold winters.', gpa_note_en='Among first-years who submitted class rank (18.3% of the class), 85.6% were in the top 10% of their high school class (CDS 2024-25 C10)' where id=12;
update schools set intro_en='An urban campus in the College Hill area of Providence, Rhode Island.', what_they_value_en='In CDS 2025-26 C7, the factors officially marked ''Very Important'' are rigor, class rank, GPA, standardized test scores, essays, recommendations, talent/ability, and character. Extracurricular activities are Important; interview and level of applicant''s interest are Not Considered. The admissions office officially states that test scores are evaluated ''based on the individual context'' in which each student applies.', location_note_en='Providence is a mid-sized city of about 190,000, about an hour by car from Boston.', gpa_note_en='Among first-years who submitted class rank (29.3% of the class), 93% were in the top 10% of their high school class (CDS 2025-26 C10)' where id=13;
update schools set intro_en='A rural-style campus in the small town of Hanover, New Hampshire.', what_they_value_en='In CDS 2025-26 C7, the factors officially marked ''Very Important'' are rigor, class rank, GPA, standardized test scores, essays, recommendations, extracurricular activities, and character. It is the only one of the five schools where level of applicant''s interest is officially marked ''Considered''. The admissions office officially states that test scores are superscored (best section scores combined).', location_note_en='Hanover is a small college town of about 10,000, surrounded by nature, with long, snowy winters.', gpa_note_en='Among first-years who submitted class rank (44% of the class), 96% were in the top 10% of their high school class (CDS 2025-26 C10)' where id=14;
update schools set intro_en='An urban campus in Morningside Heights, Manhattan, New York City.', what_they_value_en='In CDS 2024-25 C7, the factors officially marked ''Very Important'' are rigor, class rank, GPA, essays, recommendations, extracurricular activities, and character. Test scores are Considered; level of applicant''s interest is Not Considered. The admissions office officially describes a holistic review that carefully considers the whole application on a foundation of academic excellence, and takes into account personal circumstances and opportunity.', location_note_en='Located in Manhattan, New York, the largest US city, with strong access to public transit and city infrastructure.', gpa_note_en='Among first-years who submitted class rank (25.7% of the class), 94% were in the top 10% of their high school class (CDS 2024-25 C10)' where id=15;
update schools set intro_en='A public university in Berkeley, California, with an urban campus on the east side of San Francisco Bay.', what_they_value_en='Evaluated under the UC-wide comprehensive review''s 13 criteria: A-G course GPA, honors/AP/IB courses taken and grades, achievement relative to the opportunities at your high school, special talents/achievements/leadership, and academic achievement in light of personal circumstances. Per CDS 2025-26, ''Very Important'' factors are rigor, GPA, and essays (PIQs); extracurricular activities, character, volunteer work, and work experience are ''Important''. (Source: UC ''How applications are reviewed'' official page and UC Berkeley CDS 2025-26 C7)', location_note_en='Berkeley is a college city of about 120,000 across the bay from San Francisco, with a mild climate year-round and BART transit to San Francisco.', gpa_note_en='The middle 50% high school GPA of Fall 2026 admits was 4.16–4.28 (weighted); per CDS 2025-26, the average high school GPA of enrolled first-years was 3.90 (out of 4.0).' where id=16;
update schools set intro_en='A private research university near the Museum District of Houston, Texas, with a green campus inside a major city.', what_they_value_en='Per CDS 2025-26, ''Very Important'' factors are broad: rigor, class rank, GPA, standardized test scores, essays, recommendations, extracurricular activities, talent, and character. Level of applicant''s interest is also ''Considered''. Rice officially states that test scores are one of many factors in holistic review. (Source: Rice CDS 2025-26 C7·C8F, admission.rice.edu)', location_note_en='Houston is the 4th-largest US city, with a humid subtropical climate and hot summers; the campus sits next to the Texas Medical Center, the world''s largest medical complex.', gpa_note_en='Per CDS 2025-26, 90% of first-years were in the top 10% of their high school class (GPA distribution not reported).' where id=17;
update schools set intro_en='A large public university in the Westwood area of Los Angeles, California, with an urban campus.', what_they_value_en='Evaluated under the UC-wide comprehensive review''s 13 criteria: A-G course GPA, advanced courses such as AP/IB and grades, achievement relative to the opportunities at your high school, special talents, awards, and leadership experience, and academic achievement in light of life circumstances. Per CDS 2025-26, ''Very Important'' factors are rigor, GPA, and application essays (PIQs). (Source: UC ''How applications are reviewed'' official page and UCLA CDS 2025-26 C7)', location_note_en='Los Angeles is the second-largest US city with a mild Mediterranean climate year-round; the campus is in a residential/commercial area about 8 km from the Pacific coast.', gpa_note_en='The middle 50% high school GPA of Fall 2026 admits was 4.20–4.30 (weighted).' where id=18;
update schools set intro_en='A private research university near downtown Nashville, Tennessee, with an urban campus that is designated an arboretum in its entirety.', what_they_value_en='Per CDS 2025-2026, ''Very Important'' factors are rigor, class rank, GPA, essays, extracurricular activities, and character/personal qualities. Standardized test scores and talent are ''Important''; recommendations and interview weigh less. (Source: Vanderbilt CDS 2025-2026 C7)', location_note_en='Nashville is a mid-sized city of about 700,000 known as a music-industry hub; the campus is about 2.5 km from downtown, with a four-season climate.', gpa_note_en='Per CDS 2025-2026, the average high school GPA of first-years was 3.90 (out of 4.0), and 91% were in the top 10% of their high school class.' where id=19;
update schools set intro_en='A private research university in Pittsburgh, Pennsylvania, with a campus in the city''s Oakland neighborhood.', what_they_value_en='Per the latest CDS (2025-26) C7, rigor, class rank, GPA, extracurricular activities, character/personal qualities, and volunteer work are rated ''Very Important''. Essays, recommendations, talent, and first-generation status are ''Important''; standardized test scores are ''Considered''. CMU officially states that the weight of factors varies by college (program).', location_note_en='Pittsburgh is a mid-sized city in the Northeastern US with four distinct seasons; the campus is in a university district next to the University of Pittsburgh and others.', gpa_note_en='Average high school GPA of first-years was 3.89; 43.9% had a 4.0 and 82.5% were in the top 10% of their high school class (CDS 2025-26 C10-C12).' where id=20;
update schools set intro_en='A public research university in Ann Arbor, Michigan, with a campus in a mid-sized, university-centered city.', what_they_value_en='Per CDS 2025-26 C7, rigor and GPA are ''Very Important'', while test scores, essays, recommendations, character, and first-generation status are ''Important''. The official Selection Process page describes holistic review with no single criterion, names achievement in a rigorous curriculum plus leadership, awards, and service outside the classroom as key factors, and states that legacy (alumni children) is not considered.', location_note_en='Ann Arbor is a classic college town about 45 minutes by car west of Detroit, with long, cold winters in a Great Lakes climate.', gpa_note_en='Average high school GPA of first-years was 3.9, and 93.9% had a GPA of 3.75 or higher (CDS 2025-26 C11-C12).' where id=21;
update schools set intro_en='A Catholic private university in Notre Dame, Indiana, near South Bend, with a suburban campus.', what_they_value_en='The official evaluation criteria page emphasizes taking the most challenging courses available at your high school and earning strong grades, extracurriculars that show ''leading and making an impact'', recommendations from academic teachers and counselors, and essays that show who you really are. Per CDS 2025-2026, rigor, class rank, GPA, essays, recommendations, extracurricular activities, talent, character, and volunteer work are ''Very Important'', while standardized test scores are ''Important''. (Source: admissions.nd.edu Evaluation Criteria and ND CDS 2025-2026 C7)', location_note_en='Located in a small metro area of about 100,000 people about 150 km east of Chicago, with cold, snowy winters in a Great Lakes climate.', gpa_note_en='Per CDS 2025-2026, 92% of first-years were in the top 10% of their high school class (GPA distribution not reported).' where id=22;
update schools set intro_en='A private research university in the suburbs of St. Louis, Missouri; the main Danforth Campus borders Forest Park, a large city park.', what_they_value_en='Per CDS 2024-25 C7, rigor, class rank, GPA, standardized test scores, essays, recommendations, talent/ability, and character/personal qualities are all marked ''Very Important''. Extracurricular activities, first-generation status, volunteer work, and work experience are ''Important''; level of applicant''s interest (demonstrated interest) is ''Considered''. Source: WashU official Common Data Set 2024-25 C7.', location_note_en='St. Louis is a mid-sized Midwestern city; the campus is not downtown but in a suburban residential area on the city''s western edge, making for a relatively quiet setting.', gpa_note_en='Average high school GPA of first-years was 4.19 (based on the 90% who submitted, on the scale reported by their schools), and 86% were in the top 10% of their high school class (CDS 2024-25 C10-C12).' where id=23;
update schools set intro_en='A private research university in Atlanta, Georgia; undergraduate applications are split between two campuses, Emory College and Oxford College.', what_they_value_en='In its latest CDS (2025-26) C7, Emory officially reports rigor, GPA, extracurricular activities, talent/ability, and character/personal qualities as ''Very Important''. Essays, recommendations, volunteer work, and (if submitted) standardized test scores are rated ''Important''.', location_note_en='A suburban campus in the Druid Hills residential area of metro Atlanta, with a Southern US climate of hot summers and mild winters.', gpa_note_en='Average high school GPA of first-years was 3.80; 63% were in the 3.75-3.99 range, and 76% were in the top 10% of their class (CDS 2025-26 C10-C12).' where id=24;
update schools set intro_en='The oldest Catholic (Jesuit) private university in the US, located in Washington, D.C.; undergraduates are divided into 6 schools.', what_they_value_en='Per CDS 2025-26 C7, rigor, class rank, GPA, standardized test scores, essays, recommendations, talent/ability, and character are all rated ''Very Important'' — a structure that puts the full range of academic factors at the top. Interview and extracurricular activities are ''Important'', and Georgetown is one of the few universities that still requires SAT/ACT submission.', location_note_en='An urban campus in the Georgetown district of northwest Washington, D.C., with a four-season climate, close to federal agencies and international organizations.', gpa_note_en='87% of first-years were in the top 10% and 97% in the top 25% of their high school class (CDS 2025-26 C10; GPA distribution and average not reported).' where id=25;
update schools set intro_en='North Carolina''s public flagship university and one of the oldest public universities in the US.', what_they_value_en='Per CDS 2025-26 C7, rigor, essays, recommendations, extracurricular activities, talent/ability, character, and state residency are rated ''Very Important'' — as a public university, preference for North Carolina residents is officially stated. Test scores are ''Considered''; GPA and class rank are ''Important''.', location_note_en='Chapel Hill is a small university-centered college town that forms the Research Triangle with Raleigh and Durham, with a mild climate.', gpa_note_en='Average high school GPA of first-years was 4.47 (weighted); 94.6% had a weighted 4.0 or higher, and 76.2% were in the top 10% of their class (CDS 2025-26 C10-C12).' where id=26;
update schools set intro_en='Virginia''s public flagship university, founded by Thomas Jefferson; part of the campus is a UNESCO World Heritage Site.', what_they_value_en='Per CDS 2024-25 C7, rigor, class rank, GPA, character/personal qualities, and state residency are rated ''Very Important'' — as a public university, preference for Virginia residents is officially stated. Essays, recommendations, extracurricular activities, and talent are ''Important''; test scores are ''Considered''.', location_note_en='Charlottesville is a small college city about 2.5 hours by car from Washington, D.C., with a four-season climate.', gpa_note_en='90.5% of first-years had a high school GPA of 4.0 (among those submitting), and 84% were in the top 10% of their class (CDS 2024-25 C10-C11; average GPA not reported).' where id=27;
update schools set intro_en='California''s oldest private research university, located in Los Angeles; admission is by major/school.', what_they_value_en='Per CDS 2025-26 C7, rigor, GPA, essays, recommendations, and character/personal qualities are rated ''Very Important''. Extracurricular activities and talent/ability are ''Important'', and USC officially reports that class rank, interview, and level of applicant''s interest are not considered.', location_note_en='An urban campus in University Park near downtown LA, with a mild, dry Mediterranean climate year-round.', gpa_note_en='Average high school GPA of first-years was 3.85; 28.2% had a 4.0 and 52% were in the 3.75-3.99 range (CDS 2025-26 C11-C12).' where id=28;
update schools set intro_en='A public research university in the University of California (UC) system, especially strong in STEM, biosciences, and data.', what_they_value_en='Per CDS 2025-2026 C7, the three ''Very Important'' factors are rigor, academic GPA, and application essays (PIQs). Test scores, recommendations, and interviews are not considered at all; extracurricular activities, talent, and character are ''Important''.', location_note_en='The campus is in the coastal La Jolla area of San Diego, California.', gpa_note_en='Per CDS 2025-2026, the average high school GPA of Fall 2025 entrants was 3.88, and 85% had a 3.75 or higher.' where id=29;
update schools set intro_en='Florida''s flagship public university and a large comprehensive research university.', what_they_value_en='Per CDS 2024-2025 C7, ''Very Important'' factors are rigor, academic GPA, extracurricular activities, and talent/ability. Test scores and essays are ''Important''; recommendations and level of applicant''s interest are not considered.', location_note_en='A college-town campus in Gainesville, Florida.', gpa_note_en='Per CDS 2024-2025, the average high school GPA of Fall 2024 entrants was 3.92, and 53% had a 4.0.' where id=30;
update schools set intro_en='Texas''s flagship public university, where admission by major — CS, engineering, business (McCombs) and others — is intensely competitive.', what_they_value_en='Per the official admissions review guidance, UT conducts holistic review of class rank, rigor, test scores, awards and achievements, activities and service, and essays, and also considers how competitive the intended major is. In CDS 2025-2026 C7, no factor is designated ''Very Important''; most academic and non-academic factors are marked ''Considered''.', location_note_en='The campus is in downtown Austin, the Texas state capital.', gpa_note_en=NULL where id=31;
update schools set intro_en='A leading public engineering-and-computing university in the US, with a clear STEM focus in both practice and research.', what_they_value_en='Per CDS 2025-2026 C7, ''Very Important'' factors are rigor, academic GPA, character/personal qualities, and (Georgia) state residency. Essays and extracurricular activities are ''Important'', and evidence of interest in and preparation for the intended major is part of the review (official Major Selection page).', location_note_en='The campus is in Midtown Atlanta, Georgia.', gpa_note_en='Per CDS 2025-2026, the average high school GPA of Fall 2025 entrants was 4.17, and 95.9% had a 4.0 or higher.' where id=32;
update schools set intro_en='A large private research university in the heart of Manhattan, New York; you apply to a specific school (college).', what_they_value_en='Per CDS 2025-2026 C7, ''Very Important'' factors are rigor, academic GPA, essays, recommendations, and character/personal qualities. Test scores are ''Important'', while level of applicant''s interest (demonstrated interest), extracurricular activities, and talent are ''Considered''.', location_note_en='An urban campus around Greenwich Village in Manhattan, New York City, New York.', gpa_note_en='Per CDS 2025-2026, the average high school GPA of Fall 2025 entrants was 3.81, and 71.9% had a 3.75 or higher.' where id=33;
update schools set intro_en='A public research university in the University of California (UC) system.', what_they_value_en='Evaluated under the UC official comprehensive review''s 13 criteria, considering A-G course GPA, breadth and rigor of courses (Honors/AP/IB), achievement relative to your school''s environment, outstanding achievement or talent in a specific area, upward grade trends, and context such as family and school circumstances. Per CDS 2025-2026 C7, Very Important factors are rigor and academic GPA; essays, activities, talent, and character are Important.', location_note_en='Located in Davis, California (near the state capital, Sacramento).', gpa_note_en='Average high school GPA of Fall 2025 entrants was 4.03 (weighted); 66.1% had a GPA of 4.0 (CDS C11-C12)' where id=34;
update schools set intro_en='A public research university in the University of California (UC) system.', what_they_value_en='Evaluated under the UC official comprehensive review''s 13 criteria, considering A-G course GPA, rigor of courses taken, achievement relative to your school''s opportunities, special talents and achievements, upward grade trends, and more, all in context. Per CDS 2024-2025 C7, Very Important factors are rigor, academic GPA, essays, extracurricular activities, talent/ability, volunteer work, and work experience — activities carry relatively heavy weight.', location_note_en='Located in Irvine, Orange County, California.', gpa_note_en=NULL where id=35;
update schools set intro_en='A private research university in the Jesuit tradition, founded in 1863.', what_they_value_en='Per CDS 2024-2025 C7, the two Very Important factors are rigor and academic GPA. The official test-optional page describes a holistic review that considers grades, rigor of curriculum, writing, activities in and out of school, and recommendations together, and states that scores are ''just one of many factors, not a sole determining factor''.', location_note_en='Located in Chestnut Hill, a suburb of Boston, Massachusetts.', gpa_note_en='Among Fall 2024 entrants who submitted class rank (27%), 90% were in the top 10% (CDS C10; GPA distribution and average not reported)' where id=36;
update schools set intro_en='A private research university near Boston, founded in 1852.', what_they_value_en='Per CDS 2025-2026 C7, Very Important factors are rigor, class rank, academic GPA, essays, recommendations, and character/personal qualities. Extracurricular activities and talent are Important; level of applicant''s interest (demonstrated interest) and interview are Considered.', location_note_en='Located in Medford/Somerville, Massachusetts (near Boston).', gpa_note_en='Among Fall 2025 entrants who submitted class rank (21%), 87% were in the top 10% (CDS C10; GPA distribution and average not reported)' where id=37;
update schools set intro_en='Illinois''s flagship public research university, founded in 1867.', what_they_value_en='Per CDS 2025-2026 C7, Very Important factors are rigor and academic GPA. Essays are Important; test scores, extracurricular activities, and talent are Considered. Because admission is by major, preparation related to your intended major effectively becomes the core context of the review.', location_note_en='Located in the twin cities of Urbana-Champaign, Illinois, about 220 km south of Chicago.', gpa_note_en='Among Fall 2025 entrants who submitted class rank (21.7%), 61.6% were in the top 10% and 88.8% in the top 25% (CDS C10; average GPA not reported)' where id=38;
update schools set intro_en='Wisconsin''s flagship public research university, a large comprehensive university with about 38,000 undergraduates.', what_they_value_en='Per CDS 2024-2025 C7, the only two Very Important factors are rigor and academic GPA; test scores and extracurricular activities rank lower. The official admissions page (What We Look For) says it evaluates top grades in challenging courses (Honors/AP/IB), your personal story through essays, and leadership and community contribution together.', location_note_en='Located in Madison, the Wisconsin state capital, on a college-town campus surrounded by lakes.', gpa_note_en='Average high school GPA of Fall 2024 entrants was 3.90; 52.7% had a GPA of 4.0 (CDS C11-C12)' where id=39;
update schools set intro_en='A UC-system public research university on the California coast in Santa Barbara, offering 85 majors across 3 colleges.', what_they_value_en='The official page states that achievement is evaluated in the context of opportunity and circumstances under the 13 factors of the UC-wide comprehensive review. Per CDS 2025-26 C7, Very Important factors are academic GPA and application essays; test scores, recommendations, and interviews are not considered at all.', location_note_en='Located on the coast in Santa Barbara, California, about 150 km northwest of Los Angeles.', gpa_note_en='Average high school GPA of Fall 2025 entrants was 4.29 (weighted); 87.8% had a GPA of 4.0 (CDS 2025-26 C11-C12)' where id=40;
update schools set intro_en='A large public flagship research university in Columbus, Ohio, running one of the largest single campuses in the US.', what_they_value_en='Per CDS 2024-2025 C7, Very Important factors are rigor, class rank, GPA, and standardized test scores — an academics-centered evaluation. The official admissions page (Who Gets In) states it also reviews leadership and involvement, potential contribution to a diverse campus community, and personal qualities such as collaboration and resilience.', location_note_en='Located near downtown Columbus, the Ohio state capital.', gpa_note_en='64% of Fall 2024 entrants were in the top 10% and 95% in the top 25% of their high school class (CDS C10; GPA distribution not reported)' where id=41;
update schools set intro_en='A large private research university on the Charles River in Boston, with a dozen or so undergraduate schools and colleges.', what_they_value_en='Per CDS 2024-2025 C7, Very Important factors are rigor and academic GPA, while essays, recommendations, extracurricular activities, and character are Important. Notably, level of applicant''s interest (demonstrated interest) is Considered, and BU states that for CFA (College of Fine Arts) applicants, auditions/portfolios are very important.', location_note_en='An urban campus in downtown Boston, Massachusetts.', gpa_note_en='Average high school GPA of Fall 2024 entrants was 3.9; 78% had a GPA of 3.75 or higher (CDS C11-C12)' where id=42;
update schools set intro_en='New Jersey''s flagship public university, with New Brunswick as the main campus.', what_they_value_en='Per CDS 2023-2024 C7, Very Important factors are rigor and academic GPA; recommendations, interview, and level of applicant''s interest are not considered. The official admissions profile (Fall 2025) describes a holistic review of academic achievement and grades, essays, extracurricular activities, choice of school within Rutgers, and more.', location_note_en='Located in New Brunswick, New Jersey, about an hour by train from Manhattan.', gpa_note_en='Middle 50% high school GPA of Fall 2025 regular admits (SAS) was 3.8-4.2 (varies by school: Engineering 3.9-4.3, Pharmacy 4.0-4.3)' where id=43;
update schools set intro_en='Maryland''s flagship public university, a large research university strong in STEM fields such as CS and engineering.', what_they_value_en='In CDS 2025-26 C7, the only Very Important factor is rigor of the high school curriculum. The official admissions page describes a holistic review of 23+ factors, evaluating essays, leadership, community involvement, and family/environmental context alongside grades and curriculum level.', location_note_en='Located in College Park, Maryland, within public-transit reach of downtown Washington, D.C.', gpa_note_en='Average high school GPA of Fall 2025 first-years was 4.41 (weighted), and 89.2% had a GPA of 4.0 (CDS 2025-26 C11-C12).' where id=44;
update schools set intro_en='Washington''s flagship public university in Seattle, a large research university strong in CS (Allen School), engineering, and biomedical fields.', what_they_value_en='UW''s official admissions page states that, in place of standardized tests, curriculum quality and course grades are at the center of its academic evaluation. It conducts a holistic review of the entire application, including essays and extracurricular activities, and also considers non-academic achievements and the applicant''s environmental context.', location_note_en='The campus is just north of downtown Seattle, Washington, close to the tech hub of Amazon, Microsoft, and others.', gpa_note_en=NULL where id=45;
update schools set intro_en='A private research university in Bethlehem, Pennsylvania, with highly regarded engineering and business programs.', what_they_value_en='Per CDS 2025-26 C7, Very Important factors are rigor and GPA. Lehigh is a rare private university that classifies level of applicant''s interest (demonstrated interest) as Important, so showing interest through campus visits, info sessions, and the like actually counts in the review; essays, recommendations, and extracurricular activities are also Important.', location_note_en='Located in Bethlehem, Pennsylvania, about 1.5 hours by car from both New York and Philadelphia.', gpa_note_en='GPA distribution is not reported in the CDS; among those who submitted class rank (23%), 60% were in the top 10% (CDS 2025-26 C10).' where id=46;
update schools set intro_en='A private research university in Boston, known for its Co-op program, which builds full-time work at companies into the degree.', what_they_value_en='Per CDS 2024-25 C7, the four Very Important factors are rigor, GPA, standardized test scores, and recommendations. Extracurricular activities, talent, and character are Important; level of applicant''s interest (demonstrated interest) and essays are Considered.', location_note_en='The campus is in downtown Boston, Massachusetts.', gpa_note_en='Among those who submitted a GPA, 86.8% of Fall 2024 first-years had a high school GPA of 4.0 (CDS 2024-25 C11).' where id=47;
update schools set intro_en='A public research university in West Lafayette, Indiana, highly regarded in STEM fields such as engineering and CS.', what_they_value_en='Per CDS 2025-26 C7, the three Very Important factors are rigor, GPA, and essays. The official first-year review criteria page names ''the ability to succeed in the intended major'' and the program''s capacity as review factors, so major fit directly affects admission.', location_note_en='Located in West Lafayette, Indiana, about 2 hours by car from Chicago.', gpa_note_en='Average high school GPA of Fall 2025 first-years was 3.81, and the West Lafayette campus''s official profile lists a middle 50% GPA of 3.70-4.00 (CDS 2025-26 C12).' where id=48;
update schools set intro_en='One of the first public universities in the US, founded in 1785, and Georgia''s flagship public research university.', what_they_value_en='CDS 2024-25 C7 marks two factors as Very Important — rigor and academic GPA — with standardized test scores as Important. The official First-Year Criteria page says the primary review looks at grades in core subjects (English, math, science, social studies, foreign language) and how challenging your course load was relative to what your school offers, with intellectual pursuits, leadership, service, and the like reviewed as secondary factors.', location_note_en='Located in Athens, Georgia, about 1.5 hours by car from Atlanta.', gpa_note_en='Average high school GPA of Fall 2024 entrants was 4.15 (100% submitting); 85.5% had a 3.75 or higher (CDS 2024-25 C11-C12).' where id=49;
update schools set intro_en='A private research university in Rochester, New York, known for its open curriculum and the Eastman School of Music.', what_they_value_en='Per CDS 2024-25 C7, the four Very Important factors are rigor, academic GPA, extracurricular activities, and character/personal qualities. Essays, recommendations, interview, and talent are Important, and notably, level of applicant''s interest (demonstrated interest) is also Important.', location_note_en='Located in Rochester in western New York State, about an hour by plane from New York City.', gpa_note_en='Average high school GPA of Fall 2024 entrants was 3.72 (99.8% submitting); 55.1% had a 3.75 or higher (CDS 2024-25 C11-C12, AS&E basis).' where id=50;
update schools set intro_en='A private research university in Cleveland, Ohio, strong in STEM fields such as engineering, medicine, and nursing.', what_they_value_en='Per CDS 2025-26 C7, the four Very Important factors are rigor, class rank, academic GPA, and extracurricular activities. Essays, recommendations, interview, talent, character, and volunteer work are Important; level of applicant''s interest is Considered.', location_note_en='Located in the University Circle district of Cleveland, Ohio.', gpa_note_en='Average high school GPA of Fall 2025 entrants was 3.78 (92% submitting); 64.6% had a 3.75 or higher (CDS 2025-26 C11-C12).' where id=51;
update schools set intro_en='One of Florida''s leading public research universities, a large state university with its main campus in the capital, Tallahassee.', what_they_value_en='The official application page states that all applicants are reviewed through the same holistic process, centered on grades from grades 9-11 and ACT/CLT/SAT scores. The official Admissions Guide lists an admitted-student profile of weighted GPA 4.2-4.6 and SAT 1360-1470, showing that course grades and test scores are central.', location_note_en='Located in Tallahassee, the Florida state capital.', gpa_note_en='Middle 50% weighted GPA of Fall 2024 admits was 4.2-4.6 (FSU official Admissions Guide, based on FSU''s own recalculated weighted GPA).' where id=52;
update schools set intro_en='One of Texas''s flagship public research universities, among the largest in the US with over 70,000 students, and especially big in engineering.', what_they_value_en='Per CDS 2025-26 C7, Very Important factors are rigor, class rank, academic GPA, extracurricular activities, and talent/ability. The official first-year application page says applicants outside the Texas top-10% automatic admission are reviewed holistically, looking at academic factors (courses taken, grades, rigor, GPA, class rank) together with non-academic factors (extracurricular activities, service, leadership, work experience).', location_note_en='Located in College Station, Texas, about 1.5 hours by car from Houston.', gpa_note_en='GPA distribution is not reported in CDS 2025-26; among Fall 2025 entrants, 71.6% were in the top 10% and 93.1% in the top 25% of their high school class (72.2% submitted rank).' where id=53;
update schools set intro_en='Virginia''s leading public engineering-oriented research university, with large engineering and computer science programs.', what_they_value_en='Per CDS 2023-24 C7, Very Important factors are rigor, GPA, essays, first-generation status, and geographical residence/state residency. The official admissions guidance names rigor within your school''s context and grade trends, along with ''intended major'' as an explicit review factor; Virginia Tech reviews by major.', location_note_en='Located in Blacksburg, Virginia.', gpa_note_en='Average high school GPA of first-years was 4.06 (96% submitting, CDS 2023-24 C12, Fall 2023 entrants).' where id=54;
update schools set intro_en='A private research university in North Carolina that emphasizes small-scale undergraduate teaching and a low student-to-faculty ratio.', what_they_value_en='Per CDS 2024-25 C7, Very Important factors are rigor, class rank, GPA, essays, and character/personal qualities. Standardized test scores are only ''Considered'', and interview, activities, and talent are Important — a school that focuses on the academic record, writing, and character.', location_note_en='Located in Winston-Salem, North Carolina.', gpa_note_en='Average high school GPA not disclosed (no response to CDS C12). 64.2% were in the top 10% of their high school class (based on the 18% who submitted rank, C10).' where id=55;
update schools set intro_en='Founded in 1693, the second-oldest college in the US and a Virginia public university known as a ''Public Ivy''.', what_they_value_en='Per CDS 2025-26 C7, the list of Very Important factors is very broad: rigor, class rank, GPA, essays, recommendations, extracurricular activities, talent, character, state residency, volunteer work, and work experience. A public liberal-arts-style university that evaluates activities, character, and writing broadly alongside the academic record.', location_note_en='Located in Williamsburg, Virginia.', gpa_note_en='Average high school GPA 4.34 (weighted scale, 88% submitting); 88.9% had a 4.0 or higher; 79% were in the top 10% of their high school class (based on the 30% who submitted rank). CDS 2025-26.' where id=56;
update schools set intro_en='The newest campus in the UC system, opened in 2005 — a small public university that nonetheless holds R1 research status.', what_they_value_en='Per official UC requirements, applicants are evaluated by comprehensive review without test scores: completing the 15 A-G college-preparatory courses and a GPA (minimum 3.0; 3.4 for nonresidents) are the basic requirements (UC first-year requirements page). UC Merced''s official guidance likewise lists only coursework- and GPA-based requirements, and SAT/ACT are not used for admission or scholarships.', location_note_en='Located in Merced, in California''s Central Valley.', gpa_note_en='Middle 50% high school GPA of admits was 3.57-4.16 (Fall 2026 cycle, UC official first-year admit data). Minimum requirement: GPA 3.0 (California residents), 3.4 (nonresidents/international).' where id=57;
update schools set intro_en='A Catholic private university in the Augustinian tradition, relatively strong in business, engineering, and nursing.', what_they_value_en='Per CDS 2025-26 C7, the three Very Important factors are rigor, GPA, and essays. Recommendations, activities, talent, character, and volunteer work are Important; level of applicant''s interest (demonstrated interest) and interview are not considered. The review centers on the academic record and essays.', location_note_en='Located in Villanova, Pennsylvania, a suburb of Philadelphia.', gpa_note_en='Average high school GPA 3.87; 81% were in the top 10% of their high school class (based on the 19% who submitted rank). CDS 2025-26, Fall 2025 entrants.' where id=58;
update schools set intro_en='A private research university in downtown Washington, D.C., known for its programs in international affairs, politics, and policy.', what_they_value_en='Per the 2025-26 CDS C7, only two factors — rigor and GPA — are Very Important; essays and recommendations are Important. The official Test Optional admissions page states that ''the grades you earned in high school and the difficulty of your coursework are always the most important part of GW''s evaluation''. Level of applicant''s interest (demonstrated interest) is also Considered.', location_note_en='The Foggy Bottom campus in Washington, D.C., within walking distance of the White House, State Department, and more.', gpa_note_en='Average GPA not reported in the CDS; among those who submitted class rank (20.8%), 44% were in the top 10% (2025-26 CDS C10)' where id=59;
update schools set intro_en='Pennsylvania''s leading public university; University Park is the main campus, and the undergraduate population is among the largest in the US.', what_they_value_en='Per the 2024-25 CDS C7, academic GPA is the only Very Important factor; rigor is Important, and essays, recommendations, and extracurricular activities are Not Considered. CDS C6 states that ''admission to Penn State is competitive and based on academic credentials''. Penn State announced officially that for applicants who don''t submit test scores, it focuses on grades in courses related to the intended major.', location_note_en='Located in State College, a college town in central Pennsylvania.', gpa_note_en='Average high school GPA of first-years was 3.84 (Fall 2024, 95.2% submitting, 2024-25 CDS C12)' where id=60;
update schools set intro_en='A Jesuit private university in Silicon Valley, known for undergraduate-focused teaching and access to the tech industry.', what_they_value_en='Per the 2024-25 CDS C7, the academic factors rigor, GPA, and essays and the non-academic factors extracurricular activities, talent, character, volunteer work, and work experience are all marked Very Important — a broad, comprehensive review. Level of applicant''s interest (demonstrated interest) is also Important. You choose one of 3 schools when applying and are evaluated by that school''s standards (official admissions office).', location_note_en='The campus is in Santa Clara, California, in the heart of Silicon Valley.', gpa_note_en='Average high school GPA of first-years was 3.72 (Fall 2025, 100% submitting, 2025-26 CDS C12)' where id=61;
update schools set intro_en='A research university in the State University of New York (SUNY) system, an AAU member with strong STEM programs.', what_they_value_en='Per the 2025-26 CDS C7, rigor, GPA, standardized test scores, and essays are Very Important, and recommendations are Important. Most non-academic factors such as extracurricular activities and character are only Considered — an academics-centered evaluation structure.', location_note_en='Located in Stony Brook on Long Island, New York, about 100 km east of Manhattan.', gpa_note_en='Average high school grade 94.48/100 (reported on a 100-point scale); 45% had a GPA of 4.0 (Fall 2025, 2025-26 CDS C11-C12)' where id=62;
update schools set intro_en='Minnesota''s leading public research university, with a large campus spanning the two cities of Minneapolis and St. Paul.', what_they_value_en='The official admissions office states that it conducts holistic review with no automatic cutoffs, but that ''the strongest predictor of college success is academic preparation'', so it puts the heaviest weight on the high school academic record. Per the 2024-25 CDS C7, rigor, class rank, and GPA are Very Important. Non-academic factors (talent, service, overcoming challenges, etc.) are considered as context factors.', location_note_en='Campuses are in Minneapolis and St. Paul (the Twin Cities), Minnesota.', gpa_note_en='Average GPA not reported in the CDS; among those who submitted class rank (38.4%), 36.3% were in the top 10% (Fall 2024, 2024-25 CDS C10)' where id=63;
commit;
